/**
 * The 3D views (crates/skill-viz3d, on threers), compiled to WebAssembly.
 * `pkg/` is generated by `npm run build:viz3d` and committed, so a frontend
 * build needs no Rust toolchain; rebuild it after changing the crate.
 */

import init, * as viz from "./pkg/skill_viz3d.js";
import wasmUrl from "./pkg/skill_viz3d_bg.wasm?url";

export type { HeadViewer, SceneViewer } from "./pkg/skill_viz3d.js";

let ready: Promise<typeof viz> | null = null;

/** Load and instantiate the module once; every view shares it. */
export function loadViz3d(): Promise<typeof viz> {
  ready ??= init({ module_or_path: wasmUrl }).then(() => viz);
  return ready;
}

/** `#rrggbb` → `0xRRGGBB`. */
export function hexColor(css: string): number {
  return Number.parseInt(css.replace("#", ""), 16);
}

/**
 * Drive a view: forward pointer and wheel input from `canvas`, keep the
 * drawing buffer sized to it, and call `frame(dt)` every animation frame.
 * Returns a function that stops all of it.
 */
export function runView(
  canvas: HTMLCanvasElement,
  view: {
    resize(w: number, h: number, dpr: number): void;
    pointerDown(button: number, x: number, y: number): void;
    pointerMove(x: number, y: number): void;
    pointerUp(button: number): void;
    wheel(deltaY: number, x: number, y: number): void;
    frame(dt: number): void;
  },
  options: { maxPixelRatio?: number; onFrame?: (dt: number) => void } = {},
): () => void {
  const at = (e: { clientX: number; clientY: number }) => {
    const r = canvas.getBoundingClientRect();
    return [e.clientX - r.left, e.clientY - r.top] as const;
  };
  const down = (e: PointerEvent) => {
    canvas.setPointerCapture(e.pointerId);
    const [x, y] = at(e);
    view.pointerDown(e.button, x, y);
  };
  const move = (e: PointerEvent) => {
    const [x, y] = at(e);
    view.pointerMove(x, y);
  };
  const up = (e: PointerEvent) => {
    if (canvas.hasPointerCapture(e.pointerId)) canvas.releasePointerCapture(e.pointerId);
    view.pointerUp(e.button);
  };
  const wheel = (e: WheelEvent) => {
    e.preventDefault();
    const [x, y] = at(e);
    // Lines and pages are a notch each; three.js's dolly treats them alike.
    const dy = e.deltaMode === 0 ? e.deltaY : Math.sign(e.deltaY) * 100;
    view.wheel(dy, x, y);
  };
  const menu = (e: Event) => e.preventDefault();
  canvas.addEventListener("pointerdown", down);
  canvas.addEventListener("pointermove", move);
  canvas.addEventListener("pointerup", up);
  canvas.addEventListener("pointercancel", up);
  canvas.addEventListener("wheel", wheel, { passive: false });
  canvas.addEventListener("contextmenu", menu);

  const size = () => {
    const r = canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, options.maxPixelRatio ?? Infinity);
    view.resize(Math.max(1, r.width), Math.max(1, r.height), dpr);
  };
  size();
  const ro = new ResizeObserver(size);
  ro.observe(canvas);

  let raf = 0;
  let last = performance.now();
  const tick = (now: number) => {
    const dt = Math.min(0.1, (now - last) / 1000);
    last = now;
    options.onFrame?.(dt);
    view.frame(dt);
    raf = requestAnimationFrame(tick);
  };
  raf = requestAnimationFrame(tick);

  return () => {
    cancelAnimationFrame(raf);
    ro.disconnect();
    canvas.removeEventListener("pointerdown", down);
    canvas.removeEventListener("pointermove", move);
    canvas.removeEventListener("pointerup", up);
    canvas.removeEventListener("pointercancel", up);
    canvas.removeEventListener("wheel", wheel);
    canvas.removeEventListener("contextmenu", menu);
  };
}

// ── Colours as three.js's `Color` makes them (colour management on) ───────

function srgbToLinear(c: number): number {
  return c < 0.04045 ? c * 0.0773993808 : (c * 0.9478672986 + 0.0521327014) ** 2.4;
}

/** `new THREE.Color(hex)`: an sRGB `0xRRGGBB`, as linear RGB (vertex colours are linear). */
export function linearFromHex(hex: number): [number, number, number] {
  return [
    srgbToLinear(((hex >> 16) & 255) / 255),
    srgbToLinear(((hex >> 8) & 255) / 255),
    srgbToLinear((hex & 255) / 255),
  ];
}

function hue2rgb(p: number, q: number, t: number): number {
  let u = t;
  if (u < 0) u += 1;
  if (u > 1) u -= 1;
  if (u < 1 / 6) return p + (q - p) * 6 * u;
  if (u < 1 / 2) return q;
  if (u < 2 / 3) return p + (q - p) * 6 * (2 / 3 - u);
  return p;
}

function linearToSrgb(c: number): number {
  return c < 0.0031308 ? c * 12.92 : 1.055 * c ** 0.41666 - 0.055;
}

/**
 * `new THREE.Color().setHSL(h, s, l)` (each 0–1). three.js takes HSL in its
 * *working* space, which is linear — not sRGB, as hex colours are — so `rgb`
 * is the HSL result as it stands. `hex` is the sRGB `0xRRGGBB` three.js's
 * `getHex()` gives back for it.
 */
export function colorFromHsl(h: number, s: number, l: number): { rgb: [number, number, number]; hex: number } {
  const hh = ((h % 1) + 1) % 1;
  const ss = Math.min(1, Math.max(0, s));
  const ll = Math.min(1, Math.max(0, l));
  let r = ll,
    g = ll,
    b = ll;
  if (ss !== 0) {
    const p = ll <= 0.5 ? ll * (1 + ss) : ll + ss - ll * ss;
    const q = 2 * ll - p;
    r = hue2rgb(q, p, hh + 1 / 3);
    g = hue2rgb(q, p, hh);
    b = hue2rgb(q, p, hh - 1 / 3);
  }
  const byte = (v: number) => Math.round(Math.min(1, Math.max(0, linearToSrgb(v))) * 255);
  return {
    rgb: [r, g, b],
    hex: (byte(r) << 16) | (byte(g) << 8) | byte(b),
  };
}
